import React, { useEffect, useState } from 'react';
import {
  Box,
  Container,
  Grid,
  Card,
  CardContent,
  Typography,
  AppBar,
  Toolbar,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  CircularProgress,
} from '@mui/material';
import {
  Dashboard,
  People,
  Emergency,
  LocationOn,
  Chat,
  Refresh,
  Visibility,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';

const AdminDashboard = () => {
  const navigate = useNavigate();

  const [dashboardData, setDashboardData] = useState({
    statistics: {
      totalUsers: 0,
      activeAlerts: 0,
      totalAlerts: 0,
      resolvedAlerts: 0,
      totalSafetyLocations: 0,
      totalChatSessions: 0,
    },
    recentAlerts: [],
    userStats: [],
    alertStats: [],
  });
  const [loading, setLoading] = useState(true);
  const [selectedAlert, setSelectedAlert] = useState(null);
  const [alertDialog, setAlertDialog] = useState(false);

  useEffect(() => {
    fetchDashboardData();
  }, []);

  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      // Simulate API call - replace with actual API call
      const mockData = {
        statistics: {
          totalUsers: 156,
          activeAlerts: 3,
          totalAlerts: 89,
          resolvedAlerts: 86,
          totalSafetyLocations: 25,
          totalChatSessions: 234,
        },
        recentAlerts: [
          {
            _id: '1',
            userId: { fullName: 'Sarah Johnson', email: 'sarah@example.com' },
            type: 'manual',
            status: 'active',
            severity: 'high',
            location: { address: 'Times Square, NY' },
            createdAt: new Date().toISOString(),
          },
          {
            _id: '2',
            userId: { fullName: 'Maria Garcia', email: 'maria@example.com' },
            type: 'shake',
            status: 'resolved',
            severity: 'medium',
            location: { address: 'Central Park, NY' },
            createdAt: new Date(Date.now() - 3600000).toISOString(),
          },
        ],
        userStats: [
          { _id: '2024-01-01', count: 5 },
          { _id: '2024-01-02', count: 8 },
          { _id: '2024-01-03', count: 12 },
        ],
        alertStats: [
          { _id: 'manual', count: 45 },
          { _id: 'voice', count: 23 },
          { _id: 'shake', count: 21 },
        ],
      };

      setDashboardData(mockData);
    } catch (error) {
      console.error('Failed to fetch dashboard data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleViewAlert = (alert) => {
    setSelectedAlert(alert);
    setAlertDialog(true);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'active':
        return 'error';
      case 'resolved':
        return 'success';
      case 'false_alarm':
        return 'warning';
      default:
        return 'default';
    }
  };

  const getSeverityColor = (severity) => {
    switch (severity) {
      case 'critical':
        return 'error';
      case 'high':
        return 'warning';
      case 'medium':
        return 'info';
      case 'low':
        return 'success';
      default:
        return 'default';
    }
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleString();
  };

  if (loading) {
    return (
      <Box display="flex" justifyContent="center" alignItems="center" minHeight="100vh">
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      {/* Header */}
      <AppBar position="static" elevation={1}>
        <Toolbar>
          <Dashboard sx={{ mr: 2 }} />
          <Typography variant="h6" sx={{ flexGrow: 1 }}>
            NIVRA Admin Dashboard
          </Typography>
          <IconButton color="inherit" onClick={fetchDashboardData}>
            <Refresh />
          </IconButton>
          <Button color="inherit" onClick={() => navigate('/dashboard')}>
            User View
          </Button>
        </Toolbar>
      </AppBar>

      <Container maxWidth="xl" sx={{ py: 3 }}>
        {/* Statistics Cards */}
        <Grid container spacing={3} mb={4}>
          <Grid item xs={12} sm={6} md={2}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center">
                  <People color="primary" sx={{ mr: 2 }} />
                  <Box>
                    <Typography variant="h4">
                      {dashboardData.statistics.totalUsers}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Total Users
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center">
                  <Emergency color="error" sx={{ mr: 2 }} />
                  <Box>
                    <Typography variant="h4" color="error">
                      {dashboardData.statistics.activeAlerts}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Active Alerts
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center">
                  <Emergency color="warning" sx={{ mr: 2 }} />
                  <Box>
                    <Typography variant="h4">
                      {dashboardData.statistics.totalAlerts}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Total Alerts
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center">
                  <Emergency color="success" sx={{ mr: 2 }} />
                  <Box>
                    <Typography variant="h4" color="success.main">
                      {dashboardData.statistics.resolvedAlerts}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Resolved
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center">
                  <LocationOn color="info" sx={{ mr: 2 }} />
                  <Box>
                    <Typography variant="h4">
                      {dashboardData.statistics.totalSafetyLocations}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Safety Locations
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} md={2}>
            <Card>
              <CardContent>
                <Box display="flex" alignItems="center">
                  <Chat color="secondary" sx={{ mr: 2 }} />
                  <Box>
                    <Typography variant="h4">
                      {dashboardData.statistics.totalChatSessions}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      Chat Sessions
                    </Typography>
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* Recent Alerts */}
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Card>
              <CardContent>
                <Typography variant="h6" gutterBottom>
                  Recent Emergency Alerts
                </Typography>
                <TableContainer component={Paper} elevation={0}>
                  <Table>
                    <TableHead>
                      <TableRow>
                        <TableCell>User</TableCell>
                        <TableCell>Type</TableCell>
                        <TableCell>Status</TableCell>
                        <TableCell>Severity</TableCell>
                        <TableCell>Location</TableCell>
                        <TableCell>Time</TableCell>
                        <TableCell>Actions</TableCell>
                      </TableRow>
                    </TableHead>
                    <TableBody>
                      {dashboardData.recentAlerts.map((alert) => (
                        <TableRow key={alert._id}>
                          <TableCell>
                            <Box>
                              <Typography variant="body2">
                                {alert.userId?.fullName || 'Unknown'}
                              </Typography>
                              <Typography variant="caption" color="text.secondary">
                                {alert.userId?.email || 'Unknown'}
                              </Typography>
                            </Box>
                          </TableCell>
                          <TableCell>
                            <Chip
                              label={alert.type}
                              size="small"
                              variant="outlined"
                            />
                          </TableCell>
                          <TableCell>
                            <Chip
                              label={alert.status}
                              size="small"
                              color={getStatusColor(alert.status)}
                            />
                          </TableCell>
                          <TableCell>
                            <Chip
                              label={alert.severity}
                              size="small"
                              color={getSeverityColor(alert.severity)}
                            />
                          </TableCell>
                          <TableCell>
                            <Typography variant="body2">
                              {alert.location.address}
                            </Typography>
                          </TableCell>
                          <TableCell>
                            <Typography variant="body2">
                              {formatDate(alert.createdAt)}
                            </Typography>
                          </TableCell>
                          <TableCell>
                            <Button
                              size="small"
                              startIcon={<Visibility />}
                              onClick={() => handleViewAlert(alert)}
                            >
                              View
                            </Button>
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                </TableContainer>
              </CardContent>
            </Card>
          </Grid>
        </Grid>
      </Container>

      {/* Alert Details Dialog */}
      <Dialog
        open={alertDialog}
        onClose={() => setAlertDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Alert Details</DialogTitle>
        <DialogContent>
          {selectedAlert && (
            <Box>
              <Typography variant="subtitle1" gutterBottom>
                <strong>User:</strong> {selectedAlert.userId?.fullName || 'Unknown'}
              </Typography>
              <Typography variant="subtitle1" gutterBottom>
                <strong>Email:</strong> {selectedAlert.userId?.email || 'Unknown'}
              </Typography>
              <Typography variant="subtitle1" gutterBottom>
                <strong>Type:</strong> {selectedAlert.type}
              </Typography>
              <Typography variant="subtitle1" gutterBottom>
                <strong>Status:</strong> {selectedAlert.status}
              </Typography>
              <Typography variant="subtitle1" gutterBottom>
                <strong>Severity:</strong> {selectedAlert.severity}
              </Typography>
              <Typography variant="subtitle1" gutterBottom>
                <strong>Location:</strong> {selectedAlert.location.address}
              </Typography>
              <Typography variant="subtitle1" gutterBottom>
                <strong>Time:</strong> {formatDate(selectedAlert.createdAt)}
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setAlertDialog(false)}>Close</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default AdminDashboard;
